mapper.select:
SELECT COALESCE(MAX(version_number), 0)
FROM character_voice_profiles
WHERE character_id = #{characterId}

INSERT INTO character_voice_profiles (
  row_version, created_at, updated_at, character_id, version_number,
  reference_asset_id, reference_scope, language, accent, voice_description,
  delivery_baseline, status, locked_at
) VALUES (
  #{rowVersion}, #{createdAt}, #{updatedAt}, #{characterId}, #{versionNumber},
  #{referenceAssetId}, #{referenceScope}, #{language}, #{accent}, #{voiceDescription},
  #{deliveryBaseline}, #{status}, #{lockedAt}
) RETURNING id
